test('overdueInvoices includes only issued and partially_paid invoices', () => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const partiallyPaidInv = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-09-02',
        lines: [{ sku: 'STICKER', qty: 5 }],
        terms: 'NET14',
      }).value,
      [],
    ).value,
    { amount: 100, date: '2026-09-03' },
  ).value;

  const paidInv = recordPayment(
    recordPayment(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-09-03',
          lines: [{ sku: 'STICKER', qty: 5 }],
        }).value,
        [],
      ).value,
      { amount: 200, date: '2026-09-04' },
    ).value,
    { amount: 288, date: '2026-09-05' },
  ).value;

  const result = overdueInvoices([draftInv, issuedInv, partiallyPaidInv, paidInv], '2026-10-15');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, issuedInv.number);
  assert.equal(result[1].number, partiallyPaidInv.number);
});

test('overdueInvoices sorts by daysOverdue most overdue first', () => {
  const inv1 = issueInvoice(
